export const MOVES: Readonly<Record<string, Move>> = Object.freeze(
  Object.fromEntries(MOVE_LIST.map((m) => [m.id, m] as const)),
);

export function getMove(id: string): Move {
  const move = MOVES[id];
  if (!move) throw new Error(`Unknown move id: ${id}`);
  return move;
}
